/** Turn a non-success response into the most specific error class that fits. */
async function toError(response: Response): Promise<ApiError> {
  let payload: unknown;
  try {
    payload = await response.json();
  } catch {
    payload = undefined;
  }

  const body = (typeof payload === 'object' && payload !== null ? payload : {}) as Record<
    string,
    unknown
  >;
  const code = typeof body['error'] === 'string' ? (body['error'] as ErrorCode) : undefined;
  const message =
    typeof body['message'] === 'string'
      ? (body['message'] as string)
      : `Request failed with status ${response.status}.`;

  if (code === 'content_revision_conflict') {
    return new ConflictError(response.status, message, {
      expected: asRevision(body['expected']),
      actual: asRevision(body['actual']),
      body,
    });
  }

  if (code === 'bundle_rejected') {
    return new ValidationError(response.status, message, {
      code: body['code'] as BundleRejectionCode,
      detail: typeof body['detail'] === 'string' ? (body['detail'] as string) : undefined,
      body,
    });
  }

  return new ApiError(response.status, code, message, body, retryAfterSeconds(response));
}

/**
 * `Retry-After`, in seconds, for the codes that carry it.
 *
 * A header rather than a body member, so it would be invisible in `body`. The
 * sync CLI needs it to back off rather than hammer a limit it has already hit.
 */
function retryAfterSeconds(response: Response): number | undefined {
  const raw = response.headers.get('retry-after');
  if (raw === null) {
    return undefined;
  }
  const seconds = Number.parseInt(raw, 10);
  return Number.isFinite(seconds) ? seconds : undefined;
}

const asRevision = (value: unknown): string | null => (typeof value === 'string' ? value : null);
